INSERT INTO feature VALUES('floating-point','types','Binary64 floating-point numbers','native-primitives','partial','ordinary',NULL,'A number written with the `f64` suffix or annotated `(n : f64)` is an IEEE 754 binary64 float, the nearest double to its decimal text; `float64.add`, `sub`, `mul`, `div`, `neg` and `exp`, the six comparisons, `from_integer` and `round` run on the machine, `exp` the same double on every host. A fraction written bare states no type and is refused by name, with no default chosen; `f32` and exact reals are still to come.','kernel-term core-term core-checker surface-lowering runtime-emitter','corpus/model/basics/floats.gandr corpus/pathological/basics/fractions.gandr','corpus/ledger/features/floating-point.gandr','#1109 #2563');
